#include <vector>

class Solution {
public:
    int maxSum(std::vector<int>& nums, int k) {
        int count[30] = {0};
        for (int x : nums) {
            for (int b = 0; b < 30; ++b) {
                if ((x >> b) & 1) {
                    count[b]++;
                }
            }
        }

        long long ans = 0;
        const int MOD = 1'000'000'007;

        for (int i = 0; i < k; ++i) {
            int val = 0;
            for (int b = 0; b < 30; ++b) {
                if (count[b] > 0) {
                    val |= (1 << b);
                    count[b]--;
                }
            }
            ans = (ans + 1LL * val * val) % MOD;
        }

        return ans;
    }
};
